def binary_count(n):
    count = 0
    while n > 0:
        count += n & 1
        n >>= 1
    return count

def parentheses_validator(s):
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}
    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)
    return not stack

