from math import sqrt

def closest_pair_points(points: list[tuple[int, int]]) -> float:
    points.sort(key=lambda p: p[0])  # Sort points by their x-coordinates
    return closest_pair_points_rec(points, 0, len(points) - 1)

def closest_pair_points_rec(points: list[tuple[int, int]], left: int, right: int) -> float:
    if right - left <= 3:
        return brute_force(points, left, right)

    mid = (left + right) // 2
    mid_point = points[mid]
    dl = closest_pair_points_rec(points, left, mid)
    dr = closest_pair_points_rec(points, mid + 1, right)
    d = min(dl, dr)

    strip = [p for p in points[left:right + 1] if abs(p[0] - mid_point[0]) < d]
    strip.sort(key=lambda p: p[1])
    for i in range(len(strip)):
        j = i + 1
        while j < len(strip) and strip[j][1] - strip[i][1] < d:
            d = min(d, euclidean_distance(strip[i], strip[j]))
            j += 1

    return d

def brute_force(points: list[tuple[int, int]], left: int, right: int) -> float:
    min_dist = float('inf')
    for i in range(left, right):
        for j in range(i + 1, right + 1):
            min_dist = min(min_dist, euclidean_distance(points[i], points[j]))
    return min_dist

def euclidean_distance(p1: tuple[int, int], p2: tuple[int, int]) -> float:
    return sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

