def staircases(n):
    if n == 1 or n == 0:
        return 1
    elif n == 2:
        return 2
    else:
        dp = [0 for _ in range(n+1)]
        dp[0], dp[1], dp[2] = 1, 1, 2
        for i in range(3, n+1):
            dp[i] = dp[i-1] + dp[i-2] + dp[i-3]
        return dp[n]

