def first_and_last_positions(nums, target):
    def findLow(nums, target):
        left = 0
        right = len(nums) - 1
        while left <= right:
            middle = (left + right) // 2
            if nums[middle] < target:
                left = middle + 1
            else:
                right = middle - 1
        return left

    def findHigh(nums, target):
        left = 0
        right = len(nums) - 1
        while left <= right:
            middle = (left + right) // 2
            if nums[middle] <= target:
                left = middle + 1
            else:
                right = middle - 1
        return right

    start = findLow(nums, target)
    high = findHigh(nums, target)
    if start <= high and high < len(nums) and nums[start] == target and nums[high] == target:
        return [start, high]
    else:
        return [-1, -1]

