    # 1, 2단게
    id = id.lower()

    for s in id:
        if s.islower() or s.isdigit() or s == '-' or s == '_' or s == '.':
            answer += s

    # 3단계
    flag = 0
    l = len(answer)
    temp = ""
    for i in range(l):
        if answer[i] == ".":
            flag = 1
        else:
            if flag == 1:
                flag = 0
                temp += "."
                temp += answer[i]
            else:
                temp += answer[i]
    answer = temp

    # 4단계
    answer = answer.strip('.')

    # 5단계
    if answer == "":
        answer += "a"

    #6단계
    if len(answer) >= 16:
        answer = answer[:15]

    answer = answer.strip('.')

    #7단계
