    xor_count_map = {0: 1}  # Initialize with xor 0 occurring once

    for num in nums:
        current_xor ^= num
        # If there's a previous subarray with xor equal to (current_xor ^ target_xor),
        # then adding this subarray to it will result in target_xor
        if current_xor ^ target_xor in xor_count_map:
            count += xor_count_map[current_xor ^ target_xor]

        # Update the count of current_xor in the map
        if current_xor in xor_count_map:
