def find_island_perimeter(grid):
    def dfs(grid,n,m,r,c):
        if r < 0 or c < 0 or r >= n or c >=m or grid[r][c] != 1:
            return 0

        grid[r][c] = 2

        perimeter = 0
        if r == 0 or grid[r-1][c] == 0: 
            perimeter += 1
        if r == n-1 or grid[r+1][c] == 0:
            perimeter += 1
        if c == 0 or grid[r][c-1] == 0:
            perimeter += 1
        if c == m-1 or grid[r][c+1] == 0:
            perimeter += 1

        return perimeter + dfs(grid,n,m,r-1,c) + dfs(grid,n,m,r+1,c) + dfs(grid,n,m,r,c-1) + dfs(grid,n,m,r,c+1)

    n = len(grid)
    if n == 0:
        return 0
    m = len(grid[0])
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                return dfs(grid,n,m,i,j)
    return 0

