    dif_list = []
    for i in range(len(s) - 1):
        dif_list.append(abs(ord(s[i]) - ord(s[i + 1])))

    dif_list.insert(0, 0)
    dif_list.append(limit + 1)

    cur_cost = 0
    max_len = 0
    start, end = 0, 0

    while start < len(dif_list) and end < len(dif_list) - 1:
        end = max(start, end)
        if cur_cost + dif_list[end] > limit:
            cur_cost -= dif_list[start]
            start += 1
        else:
            cur_cost += dif_list[end]
