    for i in range(1, score + 1):
        dp[i] += dp[i-1] if i-1 >= 0 else 0
        dp[i] += dp[i-2] if i-2 >= 0 else 0
        dp[i] += dp[i-3] if i-3 >= 0 else 0
    return dp[score]

