class Partition:
    def canPartition(self, nums):
        target = sum(nums)

        if target % 2 == 1:
            return False

        target //= 2

        dp = [0 for _ in range(target + 1)]

        for i in range(len(nums)):
            for j in range(target, nums[i] - 1, -1):
                dp[j] = max(dp[j], dp[j - nums[i]] + nums[i])

        return dp[-1] == target

