print(smallest_perimeter(30))  # Output: 22
print(smallest_perimeter(100))  # Output: 40

def power_modulo(base, exponent, module):
    if exponent == 0:
        return 1
    t = power_modulo(base, exponent//2, module) % module
    t = (t*t) % module
    if exponent % 2 == 0:
        return t
    else:
        return ((base % module) * t) % module

def max_subarray_sum_of_size_k(arr, k):
    if len(arr) < k:
        return -1
    window_sum = sum(arr[:k])
    max_sum = window_sum
    for i in range(len(arr) - k):
        window_sum = window_sum - arr[i] + arr[i+k]
        max_sum = max(max_sum, window_sum)
    return max_sum

def max_depth_of_dict(d):
    if not isinstance(d, dict) or not d:
        return 0
    return 1 + max(max_depth_of_dict(d[k]) for k in d)

