def check_balanced_parentheses(s: str) -> bool:
    stack = []
    bracket_map = {")": "(", "]": "[", "}": "{"}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False
        else:
            continue

    return stack == []

def max_len(arr):
    max_length = 0
    count = 0
    sum_dict = {0: -1}
    for i in range(len(arr)):
        if arr[i] == 0:
            count -= 1
        else:
            count += 1
        if count in sum_dict:
            max_length = max(max_length, i - sum_dict[count])
        else:
            sum_dict[count] = i
    return max_length

def is_palindrome_permutation(s):
    s = s.replace(' ', '').lower()
    d = dict()
    for char in s:
        if char in d:
            d[char] += 1
        else:
            d[char] = 1
    odd_count = 0
    for count in d.values():
        if count % 2 != 0:
            odd_count += 1
        if odd_count > 1:
            return False
    return True

