def find_fibonacci_numbers(num):
    if num == 0:
        return 0
    fibs = [1, 1]
    while fibs[-1] < num:
        fibs.append(fibs[-1] + fibs[-2])
    count = 0
    while num > 0:
        idx = len(fibs) - 1
        while fibs[idx] > num:
            idx -= 1
        num -= fibs[idx]
        count += 1
    return count

def longest_zeros(n):
    binary = bin(n)[2:]
    max_zeros = 0
    current_zeros = 0
    started = False
    for bit in binary:
        if bit == '0':
            if started:
                current_zeros += 1
            else:
                started = True
                current_zeros = 1
        else:
            if started:
                max_zeros = max(max_zeros, current_zeros)
                current_zeros = 0
    return max_zeros

def find_target_count(nums, target):
    def binSearch(nums,target,leftBiase):
        lp = 0
        rp = len(nums)-1
        mid = 0
        index = -1
        while lp<=rp:
            mid = (lp+rp)//2
            if(nums[mid] == target):
                index=mid
                if(leftBiase):
                    rp = mid-1
                else:
                    lp=mid+1
            elif(nums[mid]>target):
                rp=mid-1
            elif(nums[mid]<target):
                lp=mid+1
        return index

    left = binSearch(nums,target,True)
    right = binSearch(nums,target,False)

    if left == -1:
        return 0
    else:
        return right - left + 1

