def nth_digit_champernowne(n):
    count = 0
    digit = 1
    while True:
        range_of_digits = 9 * (10 ** (digit - 1)) * digit
        if n <= range_of_digits + count:
            break
        count += range_of_digits
        digit += 1
    n -= count
    number = 10 ** (digit - 1) + (n - 1) // digit
    if digit > 1:
        return int(str(number)[(n - 1) % digit])
    return number

