def find_longest_consecutive_zeros(n):
    binary = bin(n)[2:]
    max_gap = 0
    current_gap = 0
    previous_bit = None

    for bit in binary:
        if bit == '1':
            if previous_bit == '0':
                max_gap = max(max_gap, current_gap)
            current_gap = 0
        else:
            current_gap += 1
        previous_bit = bit

    return max_gap

