def can_set_zeros(matrix, zeros):
    R = len(matrix)
    C = len(matrix[0])
    for r, c in zeros:
        if r < 0 or r >= R or c < 0 or c >= C:
            return False
        for k in range(C):
            if matrix[r][k] == 0 and (r, k) not in zeros:
                return False
        for k in range(R):
            if matrix[k][c] == 0 and (k, c) not in zeros:
                return False
    return True

