def maxDepth(root):
    if root is None:
        return 0
    depth_l = maxDepth(root.left) + 1
    depth_r = maxDepth(root.right) + 1
    return max(depth_l, depth_r)

def segregate_element(arr):
    temp = [0 for _ in range(len(arr))]
    j = 0

    for i in range(len(arr)):
        if arr[i] < 0:
            temp[j] = arr[i]
            j += 1

    if j == len(arr) or j == 0:
        return arr

    for i in range(len(arr)):
        if arr[i] >= 0:
            temp[j] = arr[i]
            j += 1

    for k in range(len(arr)):
        arr[k] = temp[k]

    return arr

