def subarray_product_less_than_k(nums, k):
    if k <= 1:
        return 0

    prod = 1
    ans = left = 0
    for right, val in enumerate(nums):
        prod *= val
        while prod >= k:
            prod /= nums[left]
            left += 1
        ans += right - left + 1
    return ans

def uppercase(s):
    # Convert the string to a list of characters for easier manipulation
    chars = list(s)
    # Loop through the characters
    for i in range(len(chars)):
        # Check if the character is a lowercase letter
        if 'a' <= chars[i] <= 'z':
            # Convert it to uppercase by subtracting 32 from its ASCII value
            chars[i] = chr(ord(chars[i]) - 32)
    # Join the list of characters back into a string and return it
    return ''.join(chars)

