def binary_search_occurrence(arr, target):
    def find_left_index(arr, target):
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = left + (right - left) // 2
            if arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left

    def find_right_index(arr, target):
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = left + (right - left) // 2
            if arr[mid] <= target:
                left = mid + 1
            else:
                right = mid - 1
        return right

    left_index = find_left_index(arr, target)
    if left_index == len(arr) or arr[left_index] != target:
        return 0

    right_index = find_right_index(arr, target)
    return right_index - left_index + 1

