from collections import defaultdict 

def findTownJudge(N, trust):
    relationship = defaultdict(set)
    for relation in trust:
        relationship[relation[0]].add(relation[1])
    
    possibleTownJudge = None
    
    for i in range(1, N+1):
        if len(relationship[i]) == 0:
            possibleTownJudge = i
        
    for i in range(1, N+1):
        if possibleTownJudge != i:
            if possibleTownJudge not in relationship[i]:
                return -1
            
    return possibleTownJudge

def transform_to_one(n):
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            if n == 3 or n % 4 == 1:
                n -= 1
            else:
                n += 1
        steps += 1
    return steps

def is_Armstrong(num):
    order = len(str(num))
    sum = 0
    temp = num
    while temp > 0:
        digit = temp % 10
        sum += digit ** order
        temp //= 10
    if num == sum:
        return True
    else:
        return False

