def minimum_Operations_To_Palindrome(s):
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(n - 1, -1, -1):
            if i == j:
                dp[i][j] = 0
            elif i == j + 1:
                dp[i][j] = 0 if s[i] == s[j] else 1
            else:
                if s[i] == s[j]:
                    dp[i][j] = dp[i - 1][j + 1]
                else:
                    dp[i][j] = min(dp[i - 1][j], dp[i][j + 1]) + 1
    return dp[n - 1][0]

def union_sorted_lists(list1, list2):
    i, j = 0, 0
    union_list = []

    while i < len(list1) and j < len(list2):
        if list1[i] < list2[j]:
            union_list.append(list1[i])
            i += 1
        elif list1[i] > list2[j]:
            union_list.append(list2[j])
            j += 1
        else:
            union_list.append(list1[i])
            i += 1
            j += 1

    while i < len(list1):
        union_list.append(list1[i])
        i += 1

    while j < len(list2):
        union_list.append(list2[j])
        j += 1

    return union_list

