from collections import defaultdict

def count_Distinct_Subarrays(arr, k):
    def at_most_k_distinct(arr, k):
        count = defaultdict(int)
        left = 0
        result = 0
        for right, value in enumerate(arr):
            if count[value] == 0:
                k -= 1
            count[value] += 1
            while k < 0:
                count[arr[left]] -= 1
                if count[arr[left]] == 0:
                    k += 1
                left += 1
            result += right - left + 1
        return result

    return at_most_k_distinct(arr, k) - at_most_k_distinct(arr, k - 1)

from bisect import bisect_left

def max_nested_envelopes(envelopes):
    envelopes.sort(key=lambda x: (x[0], -x[1]))
    heights = [envelope[1] for envelope in envelopes]
    dp = []
    for height in heights:
        i = bisect_left(dp, height)
        if i == len(dp):
            dp.append(height)
        else:
            dp[i] = height
    return len(dp)

