def find_combinations(nums, target):
    result = []
    def dfs(path, index, target):
        if target == 0:
            result.append(path)
            return
        for i in range(index, len(nums)):
            if target - nums[i] < 0:
                break
            dfs(path + [nums[i]], i, target - nums[i])
    dfs([], 0, target)
    return result

