def max_sum_subarray(arr, k):
    if len(arr) < k:
        return None
    max_sum = sum(arr[:k])
    temp_sum = max_sum
    for i in range(k, len(arr)):
        temp_sum = temp_sum - arr[i-k] + arr[i]
        max_sum = max(max_sum, temp_sum)
    return max_sum

def string_transformation(source, target):
    len_source = len(source)
    len_target = len(target)
    dp = [[0] * (len_target + 1) for _ in range(len_source + 1)]

    for i in range(len_source + 1):
        for j in range(len_target + 1):
            if i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            elif source[i - 1] == target[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],    # delete
                                   dp[i][j - 1],    # insert
                                   dp[i - 1][j - 1]) # replace
    return dp[len_source][len_target]

from bisect import bisect_left

def length_of_longest_increasing_subsequence(nums):
    sub = []
    for x in nums:
        i = bisect_left(sub, x)
        if i == len(sub):
            sub.append(x)
        else:
            sub[i] = x
    return len(sub)

def pattern_match(s, p):
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]
    dp[0][0] = True
    for j in range(1, len(p) + 1):
        if p[j - 1] == '*' and dp[0][j - 2]:
            dp[0][j] = True

    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j - 1] == s[i - 1] or p[j - 1] == '.':
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2] or (dp[i - 1][j] and (s[i - 1] == p[j - 2] or p[j - 2] == '.'))

    return dp[-1][-1]

def convert_to_digits(number):
    if number == 0:
        return [0]
    digits = []
    while number:
        number, remainder = divmod(number, 10)
        digits.append(remainder)
    return digits[::-1]

def min_Remove_Parentheses(s):
    left, right, remove = 0, 0, 0
    for paren in s:
        if paren == '(':
            left += 1
        elif paren == ')' and left > 0:
            left -= 1
        else:
            remove += 1
    return remove + left

def find_subarray_with_given_sum(arr, target_sum):
    curr_sum = 0
    start = 0
    for end in range(len(arr)):
        curr_sum += arr[end]
        while curr_sum > target_sum and start < end:
            curr_sum -= arr[start]
