def match_pattern(word, pattern):
    i = 0
    j = 0
    while i < len(word) and j < len(pattern):
        if pattern[j] == '?' or pattern[j] == word[i]:
            i += 1
            j += 1
        else:
            return False
    if i == len(word) and j == len(pattern):
        return True
    elif i == len(word) and pattern[j] == '?':
        return match_pattern(word, pattern[j+1:])
    elif j == len(pattern) and word[i] == pattern[j-1]:
        return match_pattern(word[i+1:], pattern)
    else:
        return False

