        return 0
    length = len(nums)
    dp_len = [1] * length
    dp_num = [1] * length
    max_len = 1
    res = 0
    for i in range(1, length):
        for j in range(i):
            if nums[i] > nums[j]:
                if dp_len[j] + 1 > dp_len[i]:
                    dp_len[i] = dp_len[j] + 1
                    dp_num[i] = dp_num[j]
                elif dp_len[j] + 1 == dp_len[i]:
                    dp_num[i] += dp_num[j]
