def distinct_islands(grid):
    def dfs(i, j, grid, base):
        if i < 0 or j < 0 or i >= len(grid) or j >= len(grid[0]) or grid[i][j] != 1:
            return ""
        grid[i][j] = 0
        return base + "(" + dfs(i + 1, j, grid, "d") + dfs(i - 1, j, grid, "u") + dfs(i, j + 1, grid, "r") + dfs(i, j - 1, grid, "l") + ")"

    islands = set()
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                islands.add(dfs(i, j, grid, ""))
    return len(islands)

