def frog_jump(A):
    n = len(A)
    jumps, curr_reach, farthest = 0, 0, 0
    for i in range(n - 1):
        farthest = max(farthest, i + A[i])
        if i == curr_reach:
            jumps += 1
            curr_reach = farthest
        if curr_reach >= n - 1:
            return jumps
    return -1 if curr_reach < n - 1 else jumps

def search_element_range(nums, target):
    if not nums:
        return [-1, -1]
    lo = 0
    hi = len(nums) - 1
    center = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            center = mid
            break
        elif nums[mid] > target:
            hi = mid - 1
        else:
            lo = mid + 1
    if center == -1:
        return [-1, -1]
    else:
        lo = hi = center
        while lo - 1 >= 0 and nums[lo - 1] == target:
            lo -= 1
        while hi + 1 <= len(nums) - 1 and nums[hi + 1] == target:
            hi += 1
        return [lo, hi]

def grid_path(grid):
    m = len(grid)
    n = len(grid[0])
    dp = [[0 for _ in range(n)] for _ in range(m)]
    dp[0][0] = 1 if grid[0][0] == 0 else 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]
    return dp[m-1][n-1]

def smallest_palindrome(s, k):
    def expand_around_center(left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return s[left + 1:right]

    smallest = None
    for i in range(len(s)):
        # odd length palindrome
        palindrome1 = expand_around_center(i, i)
        # even length palindrome
        palindrome2 = expand_around_center(i, i + 1)

        if len(palindrome1) >= k and (smallest is None or len(palindrome1) < len(smallest)):
            smallest = palindrome1
        if len(palindrome2) >= k and (smallest is None or len(palindrome2) < len(smallest)):
            smallest = palindrome2

    return smallest

