def sunset_views(buildings):
    if not buildings:
        return []
    result = []
    max_height = buildings[-1]
    result.append(len(buildings) - 1)
    for i in range(len(buildings) - 2, -1, -1):
        if buildings[i] > max_height:
            result.append(i)
            max_height = buildings[i]
    return result[::-1]

def uniqueBST(n):
    if n <= 1:
        return 1
    dp = [0] * (n + 1)
    dp[0] = dp[1] = 1
    for i in range(2, n + 1):
        for j in range(i):
            dp[i] += dp[j] * dp[i - j - 1]
    return dp[n]

import re
def password_validity(password):
    if len(password) < 8:
        return False
    if not re.search("[a-z]", password):
        return False
    if not re.search("[A-Z]", password):
        return False
    if not re.search("[0-9]", password):
        return False
    if not re.search("[!@#$%^&*()_+=-{}<>?:;|.,]", password):
        return False
    return True

def countingValleys(steps, path):
    valley=0
    current=0
    for i in range(steps):
        previous=current
        if path[i]=='U':
            current+=1
        if path[i]=='D':
            current-=1
        if current==0 and i!=0:
            if previous==-1:
                valley+=1
    return valley

