from collections import deque

def max_in_subarrays(arr, k):
    if not arr or k <= 0:
        return []

    result = []
    q = deque()

    for i in range(k):
        while q and arr[i] >= arr[q[-1]]:
            q.pop()
        q.append(i)

    for i in range(k, len(arr)):
        result.append(arr[q[0]])

        while q and q[0] <= i-k:
            q.popleft()

        while q and arr[i] >= arr[q[-1]]:
            q.pop()
        q.append(i)

    result.append(arr[q[0]])
    return result

def min_cost_path(matrix):
    m = len(matrix)
    n = len(matrix[0])
    for i in range(1, n):
        matrix[0][i] += matrix[0][i-1]
    for i in range(1, m):
        matrix[i][0] += matrix[i-1][0]
    for i in range(1, m):
        for j in range(1, n):
            matrix[i][j] += min(matrix[i-1][j], matrix[i][j-1])
    return matrix[m-1][n-1]

