import re

def read_file(strs) -> dict:
    dct = {}
    for i in strs:
        l, r = i.replace(' ', '').split('=')
        r = re.findall(r'[A-Z]{2}\d{2}', r)
        dct[l] = r
    return dct

def has_cycle(graph):
    visited = set()
    for i in graph:
        if i in visited:
            continue
        stack = [i]
        visited_in_round = {i}
        while stack:
            cur = stack.pop()
            for j in graph[cur]:
                if j in visited_in_round:
                    return False
                visited_in_round.add(j)
                visited.add(j)
                stack.append(j)
    return True

def can_evaluate_excel(strs):
    graph = read_file(strs)
    return has_cycle(graph)

