def can_swap_to_palindrome(s):
    counts = {}
    odd_counts = 0
    for char in s:
        if char in counts:
            counts[char] += 1
        else:
            counts[char] = 1
    for count in counts.values():
        if count % 2 != 0:
            odd_counts += 1
    if odd_counts > 1:
        return False
    if len(s) % 2 == 0 and odd_counts == 1:
        return False
    return True

