def find_kdiff_pairs(nums, k):
    answer = 0
    cnt = Counter(nums)
    for num in set(nums):
        if k > 0 and num + k in cnt:
            answer += 1
        if k == 0 and cnt[num] > 1:
            answer += 1
    return answer

def catalan(n):
    if n <= 1:
        return 1

    res = 0
    for i in range(n):
        res += catalan(i) * catalan(n-i-1)
    return res

def busyStudent(startTime: list[int], endTime: list[int], queryTime: int) -> int:
