    return target

from collections import defaultdict

def valid_path(n, edges, source, destination):
    # first we need to create the graph based on the edges we were given
    neighbors = defaultdict(list)
    seen = set()

    # neighbors = {:[], :[]}
    for n1, n2 in edges:
        neighbors[n1].append(n2)
        neighbors[n2].append(n1)

    def dfs(start, end, seen):
        if start == end:
            return True
        if start in seen:
            return False
        seen.add(start)

        for vertex in neighbors[start]:
            if dfs(vertex, end, seen):
                return True

        return False

    return dfs(source, destination, seen)

def sum_of_factorials(number):
    def factorial(n):
        if n == 0:
            return 1
        else:
            return n * factorial(n-1)

    total = 0
    for i in range(1, number+1):
        total += factorial(i)
    return total

