def second_largest(nums):
    if len(nums) < 2:
        return None
    largest = max(nums[0], nums[1])
    second_largest = min(nums[0], nums[1])
    for i in range(2, len(nums)):
        if nums[i] > largest:
            second_largest = largest
            largest = nums[i]
        elif nums[i] > second_largest and nums[i] != largest:
            second_largest = nums[i]
    return second_largest

def solve_josephus(n, k):
    if (n == 1):
        return 1
    else:
        return (solve_josephus(n - 1, k) + k-1) % n + 1

def replace_with_next_greater(nums):
    stack = []
    res = [-1] * len(nums)
    for i in range(len(nums)):
        while stack and nums[stack[-1]] < nums[i]:
            res[stack[-1]] = nums[i]
            stack.pop()
        stack.append(i)
    return res

import heapq


def meeting_rooms_ii(intervals):
    intervals.sort()
    pq = [intervals[0][1]]
    for interval in intervals[1:]:
        if pq and interval[0] >= pq[0]:
            heapq.heappop(pq)
        heapq.heappush(pq, interval[1])
    return len(pq)

def camel_case_checker(s):
    # Check if the first character is lowercase
    if not s[0].islower():
        return False

    # Check if each subsequent character is uppercase when it starts a new word
    for i in range(1, len(s)):
        if s[i-1].islower() and not s[i].isupper():
            return False
        if s[i-1].isupper() and not s[i].islower():
            return False

    # Check for spaces or underscores
    if ' ' in s or '_' in s:
        return False

    return True

def caesar_cipher_encode(message, shift):
    result = ""
    for char in message:
        if char.islower():
            result += chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
        else:
            result += char
    return result

def count_Partition(n):
    partitions = [0 for _ in range(n + 1)]
    partitions[0] = 1
    for i in range(1, n + 1):
        for j in range(i, n + 1):
            partitions[j] += partitions[j - i]
    return partitions[n]

def count_Distinct_Partition(n):
