def minimumCoins(coins, amount):
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0

    for coin in coins:
        for x in range(coin, amount + 1):
            dp[x] = min(dp[x], dp[x - coin] + 1)
    return dp[amount] if dp[amount] != float('inf') else -1

def max_product_after_cutting(n: int) -> int:
    if n <= 3:
        return n - 1
    a, b, p = n // 3 - 1, n % 3, 1000000007
    x, rem = 3, 1
    while a > 0:
        if a % 2:
            rem = (rem * x) % p
        x = x**2 % p
        a //= 2
    if b == 0:
        return (rem * 3) % p
    if b == 1:
        return (rem * 4) % p
    return (rem * 6) % p

