def find_longest_palindromic_subseq(s: str) -> int:
    n = len(s)
    dp = [[0 for _ in range(n)] for _ in range(n)]

    for i in range(n-1, -1, -1):
        dp[i][i] = 1
        for j in range(i+1, n):
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])

    return dp[0][n-1]

def find_max_nested_list(lst):
    def dfs(lst, depth=0):
        if not isinstance(lst, list):
            return depth
        return max((dfs(x, depth + 1) for x in lst), default=depth)

    return dfs(lst) - 1

