from math import sqrt

def find_closest_points(points):
    points.sort()
    return closest_distance(points)

def closest_distance(points):
    n = len(points)
    if n <= 3:
        return brute_force_distance(points)
    mid = n // 2
    mid_point = points[mid]
    left = points[:mid]
    right = points[mid:]
    min_distance = min(closest_distance(left), closest_distance(right))
    strip = [point for point in points if abs(point[0] - mid_point[0]) < min_distance]
    strip.sort(key=lambda x: x[1])
    return check_strip(strip, min_distance)

def check_strip(strip, min_distance):
    for i in range(len(strip)):
        for j in range(i+1, len(strip)):
            if strip[j][1] - strip[i][1] >= min_distance:
                break
            min_distance = min(min_distance, sqrt((strip[j][0] - strip[i][0])**2 + (strip[j][1] - strip[i][1])**2))
    return min_distance

def brute_force_distance(points):
    min_distance = float('inf')
    for i in range(len(points)):
        for j in range(i+1, len(points)):
            min_distance = min(min_distance, sqrt((points[j][0] - points[i][0])**2 + (points[j][1] - points[i][1])**2))
    return min_distance

