def range_list(start, end, step=1):
    if step == 0:
        raise ValueError("Step cannot be zero.")
    if (step > 0 and start > end) or (step < 0 and start < end):
        return []
    return_list = []
    current = start
    while (step > 0 and current <= end) or (step < 0 and current >= end):
        return_list.append(current)
        current += step
    return return_list

def len_longest_increasing_subsequence(nums):
    if not nums:
        return 0
    dp = [1] * len(nums)
    for i in range(len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def operations_required(str1, str2):
    m, n = len(str1), len(str2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = i + j
            elif str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]

def caesar_cipher_encode(message: str, shift: int) -> str:
    encoded_message = ""
    for char in message:
        if char.isalpha():
            ascii_offset = 65 if char.isupper() else 97
            encoded_message += chr((ord(char) - ascii_offset + shift) % 26 + ascii_offset)
        else:
            encoded_message += char
    return encoded_message

def average_positive_numbers(numbers):
