from collections import Counter

def findKthSmallestPrime(arr, k):
    primes = []
    prime_count = Counter()
    is_prime = [True] * (max(arr) + 1)
    is_prime[0], is_prime[1] = False, False

    for i in range(2, len(is_prime)):
        if is_prime[i]:
            primes.append(i)
            for j in range(i*i, len(is_prime), i):
                is_prime[j] = False

    for num in arr:
        if is_prime[num]:
