def minCostPath(cost):
    """
    Traverse through the grid, updating the current cell, with the min cost
    of reaching to that cell. We only need to take into consideration the
    cell on the top and the one on the left.
    """
    m, n = len(cost), len(cost[0])
    for r in range(m):
        for c in range(n):
            if r and c:
                cost[r][c] += min(cost[r - 1][c], cost[r][c - 1])
            elif r:
                cost[r][c] += cost[r - 1][c]
            elif c:
                cost[r][c] += cost[r][c - 1]

    return cost[-1][-1]

