import heapq

def find_cheapest_cost(n, costs):
    graph = defaultdict(list)
    for u, v, w in costs:
        graph[u].append((v, w))
        graph[v].append((u, w))

    visited = [False] * n
    min_heap = [(0, 0)]
    total_cost = 0

    while min_heap:
        cost, island = heapq.heappop(min_heap)
        if visited[island]:
            continue
        visited[island] = True
        total_cost += cost
        for next_island, next_cost in graph[island]:
            if not visited[next_island]:
                heapq.heappush(min_heap, (next_cost, next_island))

    return total_cost

def max_sum_two_subarrays(A: list, L: int, M: int) -> int:
    preSum = [0] * (len(A) + 1)
    for i in range(1, len(preSum)):
        preSum[i] = preSum[i - 1] + A[i - 1]

    Lmax, Mmax, ans = preSum[L], preSum[M], preSum[L + M]
    for i in range(L + M + 1, len(preSum)):
        Lmax = max(Lmax, preSum[i - M] - preSum[i - M - L])
        Mmax = max(Mmax, preSum[i - L] - preSum[i - L - M])
        ans = max(ans, Lmax + preSum[i] - preSum[i - M], Mmax + preSum[i] - preSum[i - L])
    return ans

