def case_permutation(S: str) -> List[str]:
    result = []
    def backtrack(i, s, length, S, result):
        if i >= length:
            result.append(s)
            return

        backtrack(i+1, s+S[i], length, S, result)

        if S[i].isalpha():
            if S[i].islower():
                backtrack(i+1, s+S[i].upper(), length, S, result)
            else:
                backtrack(i+1, s+S[i].lower(), length, S, result)

    backtrack(0, "", len(S), S, result)
    return result

