from functools import lru_cache

def maxSizeSlices(slices: List[int]) -> int:
    """Find the maximum sum of non-adjacent elements in a circular array."""
    @lru_cache(None)
    def dfs(index: int, count: int, hasPre: bool, root: bool) -> int:
        """Current at index, chose count elements so far, previous element chosen or not, and if it's the root node."""
        if index == len(slices):
            if count != len(slices) // 3 or (hasPre and root):
                return -float('inf')
            return 0
        res = dfs(index + 1, count, False, root)
        if not hasPre and count + 1 <= len(slices) // 3:
            res = max(res, dfs(index + 1, count + 1, True, root) + slices[index])
        return res

    n = len(slices)
    return max(dfs(1, 1, True, True) + slices[0], dfs(1, 0, False, False))

