    return is_valid_bst(preorder[1:i]) and is_valid_bst(preorder[i:])

# Helper function to create the tree from array for testing
def array_to_tree(arr):
    if not arr:
        return None
    root = TreeNode(arr[0])
    queue = [root]
    front = 0
    index = 1
    while index < len(arr):
        node = queue[front]
        front += 1

        item = arr[index]
        index += 1
        if item is not None:
            left_number = item
            node.left = TreeNode(left_number)
            queue.append(node.left)

        if index >= len(arr):
            break

        item = arr[index]
        index += 1
        if item is not None:
            right_number = item
            node.right = TreeNode(right_number)
            queue.append(node.right)
    return root

def check_valid_bst(arr):
    root = array_to_tree(arr)
    if not root:
        return True
    stack = [(root, float('-inf'), float('inf'))]
    while stack:
        root, lower, upper = stack.pop()
        if not root:
            continue
        val = root.val
        if val <= lower or val >= upper:
            return False
        stack.append((root.right, val, upper))
        stack.append((root.left, lower, val))
    return True

