def next_Greatest_Number(n):
    n = str(n)
    length = len(n)
    i = length - 2
    while i >= 0:
        if n[i] < n[i + 1]:
            break
        i -= 1
    if i == -1:
        return -1
    j = length - 1
    while n[j] <= n[i]:
        j -= 1
    while n[j] == n[j - 1]:
        j -= 1
    n = list(n)
    n[i], n[j] = n[j], n[i]
    n[i + 1:] = reversed(n[i + 1:])
    return int("".join(n))

