def is_maze_solvable(maze, start, end):
    rows, cols = len(maze), len(maze[0])
    visited = set()
    queue = [start]

    while queue:
        row, col = queue.pop(0)
        if [row, col] == end:
            return True
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = row, col
            while 0 <= r + dr < rows and 0 <= c + dc < cols and maze[r + dr][c + dc] == 0:
                r += dr
                c += dc
            if (r, c) not in visited:
                visited.add((r, c))
                queue.append((r, c))
    return False

def longest_increasing_path(matrix):
    if not matrix:
        return 0
    n, m = len(matrix), len(matrix[0])
    dp = [[-1]*m for _ in range(n)]

    def dfs(i, j):
        if dp[i][j] != -1:
            return dp[i][j]
        directions = [(0,1),(0,-1),(1,0),(-1,0)]
        dp[i][j] = 1
        for dx, dy in directions:
            x, y = i + dx, j + dy
            if x < 0 or x >= n or y < 0 or y >= m or matrix[x][y] <= matrix[i][j]:
                continue
            dp[i][j] = max(dp[i][j], dfs(x, y) + 1)
        return dp[i][j]

    result = 0
    for i in range(n):
        for j in range(m):
            result = max(result, dfs(i, j))
    return result

