from collections import Counter, defaultdict
from itertools import groupby

def number_of_good_paths(vals, edges):
    n = len(vals)
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    parents = list(range(n))
    ranks = [0] * n

    ans = 0
    vfn = lambda x: x[1]
    vals_nodes_map = {
        v: list(nodes)
        for v, nodes in groupby(sorted(enumerate(vals), key=vfn), key=vfn)
    }
    for val in sorted(vals_nodes_map.keys()):
        for x, _ in vals_nodes_map[val]:
            for neighbor in adj[x]:
                if vals[neighbor] <= val:
                    union(neighbor, x, parents, ranks)

        ans += sum(
            (size + 1) * size // 2
            for size in Counter(
                find(x, parents) for x, _ in vals_nodes_map[val]
            ).values()
        )

    return ans

def find(x, parents):
    if parents[x] != x:
        parents[x] = find(parents[x], parents)

    return parents[x]

def union(x, y, parents, ranks):
    px, py = find(x, parents), find(y, parents)
    if px == py:
        return

    rx, ry = ranks[x], ranks[y]
    if rx < ry:
        px, py = py, px

    parents[py] = px
    if rx == ry:
        ranks[px] += 1

def search(nums, target):
    if not nums or target is None:
        return -1

    start = 0
    end = len(nums) - 1
    while start + 1 < end:
        mid = (start + end) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] >= nums[start] and (target < nums[mid] and target >= nums[start]):
            end = mid
        elif nums[mid] >= nums[start]:
            start = mid
        elif nums[mid] <= nums[end] and (target > nums[mid] and target <= nums[end]):
            start = mid
        else:
            end = mid
    if nums[start] == target:
        return start
    if nums[end] == target:
        return end

    return -1

