def max_crossing_sum(arr):
    def max_sum(left, right, mid):
        sum_left = float('-inf')
        current_sum = 0
        for i in range(mid, left-1, -1):
            current_sum += arr[i]
            if current_sum > sum_left:
                sum_left = current_sum

        sum_right = float('-inf')
        current_sum = 0
        for i in range(mid+1, right+1):
            current_sum += arr[i]
            if current_sum > sum_right:
                sum_right = current_sum

        return sum_left + sum_right

    def solve(left, right):
        if left == right:
            return arr[left]

        mid = (left + right) // 2
        left_sum = solve(left, mid)
        right_sum = solve(mid + 1, right)
        crossing_sum = max_sum(left, right, mid)

        return max(left_sum, right_sum, crossing_sum)

    return solve(0, len(arr) - 1)

