from typing import List
def has_valid_path(grid: List[List[int]]) -> bool:
    HEIGHT = len(grid)
    WIDTH = len(grid[0])
    diffs = [[1,0],[-1,0],[0,1],[0,-1]]
    streets = {
        1: ['l', 'r'],
        2 : ['u', 'd'],
        3 : ['l', 'd'],
        4: ['r', 'd'],
        5: ['l', 'u'],
        6 : ['u', 'r'],
    }
    depToArr = {
        'd' : 'u',
        'u' : 'd',
        'r' : 'l',
        'l' : 'r'
    }
    seen = set() # don't repeat work

    def dfs(r, c):
        key = r * WIDTH + c
        seen.add(key)
        # base case
        if r == HEIGHT - 1 and c == WIDTH - 1:
            return True
        for rowDiff, colDiff in diffs:
            newRow = rowDiff + r
            newCol = colDiff + c
            newKey = newRow * WIDTH + newCol
            # skip out of bounds
            if newRow == HEIGHT or newRow < 0 or newCol == WIDTH or newCol < 0:
                continue
            # skip seen
            if newKey in seen:
                continue

            # determine departure direction
            if rowDiff == 1:
                departureDirection = 'd'
            elif rowDiff == -1:
                departureDirection = 'u'
            if colDiff == 1:
                departureDirection = 'r'
            elif colDiff == -1:
                departureDirection = 'l'
            arrivalDirection = depToArr[departureDirection]

            # skip invalid rows
            if not departureDirection in streets[grid[r][c]] or not arrivalDirection in streets[grid[newRow][newCol]]:
                continue

            if dfs(newRow, newCol):
                return True
        return False
    return dfs(0, 0)

def max_value_with_swaps(arr, k):
    n = len(arr)
    if n == 1 or k == 0:
        return arr[0]

    max_val = [arr[0]] * n
    for i in range(1, n):
        max_val[i] = max(arr[i], max_val[i-1])

    result = arr[0]
    for i in range(1, n):
        if k > 0:
            result = max(result, max_val[min(i+k, n-1)])
            max_val[i] = max(max_val[i], result)
        else:
            result = max_val[i]

    return result

def cyclic_sort(nums):
    n = len(nums)
    if n <= 1:
        return True

    # Find the number of elements that are not in the right order
    disordered = 0
    for i in range(1, n):
        if nums[i-1] > nums[i]:
            disordered += 1

    # If the last and first elements are out of order, increment the counter
    if nums[n-1] > nums[0]:
        disordered += 1

    # If the array is already sorted or can be sorted with one cyclic shift, return True
    return disordered <= 1

