def calculate_expression(expression: str) -> int:
    def apply_operator(operands, operator):
        b = operands.pop()
        a = operands.pop()
        if operator == '+':
            operands.append(a + b)
        elif operator == '-':
            operands.append(a - b)
        elif operator == '*':
            operands.append(a * b)
        elif operator == '/':
            operands.append(int(a / b))

    def greater_precedence(op1, op2):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        return precedence[op1] > precedence[op2]

    def evaluate(expression):
        operands = []
        operators = []
        i = 0
        while i < len(expression):
            if expression[i] == ' ':
                i += 1
                continue
            if expression[i].isdigit():
                val = 0
                while i < len(expression) and expression[i].isdigit():
                    val = (val * 10) + int(expression[i])
                    i += 1
                operands.append(val)
                continue
            elif expression[i] == '(':
                operators.append(expression[i])
            elif expression[i] == ')':
                while operators[-1] != '(':
                    apply_operator(operands, operators.pop())
                operators.pop()
            else:
                while (operators and operators[-1] != '(' and
                       greater_precedence(operators[-1], expression[i])):
                    apply_operator(operands, operators.pop())
                operators.append(expression[i])
            i += 1
        while operators:
            apply_operator(operands, operators.pop())
        return operands[-1]

    return evaluate(expression.replace(' ', ''))

