def prime_fibonacci_sum(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    def fibonacci(n):
        if n == 0:
            return 0
        elif n == 1:
            return 1
        else:
            return fibonacci(n - 1) + fibonacci(n - 2)

    sum_primes = 0
    i = 1
    while True:
        fib1 = fibonacci(i)
        fib2 = fibonacci(i + 1)
        sum_fib = fib1 + fib2
        if is_prime(sum_fib):
            sum_primes += sum_fib
            n -= 1
            if n == 0:
                break
        i += 1
    return sum_primes

