    for i in range(2, n + 1):
        single = int(s[i-1:i])
        double = int(s[i-2:i])
        if 1 <= single <= 9:
            dp[i] += dp[i - 1]
        if 10 <= double <= 26:
            dp[i] += dp[i - 2]
    return dp[n]

