def maximum_Consecutive_Ones(nums):
    left, right, zeroCount, maxCount = 0, 0, 0, 0
    while right < len(nums):
        if nums[right] == 0:
            zeroCount += 1
        while zeroCount > 1:
            if nums[left] == 0:
                zeroCount -= 1
            left += 1
        maxCount = max(maxCount, right - left + 1)
        right += 1
    return maxCount

