def decompress(s):
    stack, currString, currNum = [], '', 0

    for i in s:
        if i.isdigit():
            currNum = currNum*10 + int(i)

        elif i == '[':
            stack.append(currString)
            stack.append(currNum)
            currString = ''
            currNum = 0

        elif i == ']':
            num = stack.pop()
            prevString = stack.pop()
            currString = prevString + num*currString

        else:
            currString += i

    return currString

def next_larger_number(n):
    num_str = str(n)
    length = len(num_str)
    i = length - 2
    while i >= 0:
        if num_str[i] < num_str[i + 1]:
            break
        i -= 1
    if i == -1:
        return -1
    j = length - 1
    while j >= 0:
        if num_str[j] > num_str[i]:
            break
        j -= 1
    num_list = list(num_str)
    num_list[i], num_list[j] = num_list[j], num_list[i]
    num_list[i + 1:] = sorted(num_list[i + 1:])
    return int(''.join(num_list))

def number_complement(num):
    # Find the highest bit set in the number
    highest_bit = 1
    while highest_bit <= num:
        highest_bit <<= 1
    highest_bit >>= 1

    # Flip all bits up to the highest bit set
    return ~num & ((1 << highest_bit.bit_length()) - 1)

