def buy_and_sell_two_at_most(prices):
    if not prices or len(prices) < 2:
        return 0
    # dp arrays to store the profits for 1 and 2 transactions
    dp = [[0, 0, 0, 0] for _ in range(len(prices))]
    dp[0][0], dp[0][1], dp[0][2], dp[0][3] = 0, -prices[0], 0, -prices[0]
    for i in range(1, len(prices)):
        # i=0 means no transaction, i=1 means 1 transaction, i=2 means 2 transactions
        dp[i][0] = dp[i - 1][0]
        dp[i][1] = max(dp[i - 1][1], dp[i - 1][0] - prices[i])
        dp[i][2] = max(dp[i - 1][2], dp[i - 1][1] + prices[i])
        dp[i][3] = max(dp[i - 1][3], dp[i - 1][2] - prices[i])
    return max(dp[-1][2], dp[-1][3] + prices[-1])

