def combination_sum4(nums: List[int], target: int) -> int:
    dp = [0] * (target + 1)
    dp[0] = 1
    for j in range(1, target+1):
        for v in nums:
            if j < v:
                continue
            dp[j] += dp[j-v]
    return dp[target]

