from functools import lru_cache

def can_form_square(nums):
    S = sum(nums)
    if S % 4: return False
    q = S // 4
    N = len(nums)
    if N <= 3: return False
    nums.sort(reverse=True)

    @lru_cache(None)
    def comb(a, b, c, d, i):
        if i == N:
            return a == q and b == q and c == q and d == q
        sides = [a, b, c, d]
        for j, s in enumerate(sides):
            if s + nums[i] <= q:
                sides[j] += nums[i]
                if comb(*sides, i + 1):
                    return True
                sides[j] -= nums[i]
        return False
    return comb(*[0, 0, 0, 0], 0)

