def max_cuboid_volume(L: int, W: int, H: int) -> int:
    sides = [L, W, H]
    sides.sort()
    L, W, H = sides
    max_volume = (L * W * H)
    if 2*H <= L and 2*H <= W:
        max_volume = max(max_volume, 4*H*H*H)
    if 2*W <= L:
        max_volume = max(max_volume, W*W*(L-2*W))
    if 2*L <= W:
        max_volume = max(max_volume, L*L*(W-2*L))
    return max_volume

from collections import deque

def minPathSteps(matrix, start, end):
    queue = deque([(start[0], start[1], 0)])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    rows, cols = len(matrix), len(matrix[0])
    visited = set()

    while queue:
        x, y, steps = queue.popleft()
        if (x, y) == (end[0], end[1]):
            return steps
        for dx, dy in directions:
            newX, newY = x + dx, y + dy
            if 0 <= newX < rows and 0 <= newY < cols and (newX, newY) not in visited and matrix[newX][newY] == 0:
                queue.append((newX, newY, steps + 1))
                visited.add((newX, newY))
    return -1

