def deepest_node(root: TreeNode):
    deepest = [root.val, 0]
    def dfs(node: TreeNode, depth: int):
        nonlocal deepest
        if not node:
            return
        if depth > deepest[1]:
            deepest = [node.val, depth]
        dfs(node.left, depth + 1)
        dfs(node.right, depth + 1)
    dfs(root, 0)
    return deepest[0]

def max_rectangle(matrix):
