def change(amount, coins):
    rows = len(coins) + 1
    cols = amount + 1
    cache = [cols * [0] for _ in range(rows)]
    for i in range(cols):
        cache[0][i] = 0
    for i in range(rows):
        cache[i][0] = 1

    for i in range(1, rows):
        coin = coins[i-1]
        for target in range(1, amount+1):
            cache[i][target] = cache[i-1][target]
            residual = target - coin
            if residual >= 0:
                cache[i][target] += cache[i][residual]

    return cache[-1][-1]

