    for i, e in enumerate(employees[1:], start=1):
        m[e] = employees[i-1]

    path1 = [employee1]
    while m[employee1]:
        path1.append(m[employee1])
        employee1 = m[employee1]

    path2 = [employee2]
    while m[employee2]:
        path2.append(m[employee2])
        employee2 = m[employee2]

    path1 = path1[::-1]
    path2 = path2[::-1]

