        temp[count] = ele[:-1]
        count += 1
    dec = {index[i]:temp[i] for i in range(len(temp))}

    for i in range(len(index)):
        least = i
        for k in range (i+1,len(index)):
            if index[k] < index[least]:
                least = k
        temp = index[i]
