    a, b = 0, 1
    while b < n:
        a, b = b, a + b
    return b == n

def ways_to_reach_stair(n):
    if n <= 1:
        return n
    first, second = 0, 1
    for _ in range(n):
        first, second = second, first + second
    return second

def count_good_numbers(n):
    def is_good_number(num):
        rotate_map = {'0': '0', '1': '1', '8': '8', '2': '5', '5': '2', '6': '9', '9': '6'}
        original = str(num)
        rotated = ''
        for digit in original:
            if digit not in rotate_map:
                return False
            rotated += rotate_map[digit]
        return original != rotated

    count = 0
    for i in range(1, n + 1):
        if is_good_number(i):
            count += 1
    return count

def descending_sort(lst):
    n = len(lst)
    for i in range(n):
        for j in range(0, n-i-1):
            if lst[j] < lst[j+1]:
                lst[j], lst[j+1] = lst[j+1], lst[j]
    return lst

def find_max_nested_sublists(lst):
    max_depth = 0
    current_depth = 0

    def dfs(sublist):
        nonlocal max_depth, current_depth
        current_depth += 1
        for elem in sublist:
            if isinstance(elem, list):
                dfs(elem)
        max_depth = max(max_depth, current_depth)
        current_depth -= 1

    dfs(lst)
    return max_depth

def count_inverse_pairs(arr):
    def merge_sort(start, end):
        if start >= end:
            return 0
        mid = (start + end) // 2
        count = merge_sort(start, mid) + merge_sort(mid + 1, end)
        i, j = start, mid + 1
        temp = []
        while i <= mid and j <= end:
            if arr[i] <= arr[j]:
                temp.append(arr[i])
                i += 1
            else:
                temp.append(arr[j])
                count += mid - i + 1
                j += 1
        temp.extend(arr[i:mid + 1])
        temp.extend(arr[j:end + 1])
        arr[start:end + 1] = temp
        return count
    return merge_sort(0, len(arr) - 1)

def sort_matrix(matrix):
    row_count = len(matrix)
    col_count = len(matrix[0])

    # Sort each row
    for i in range(row_count):
        matrix[i] = sorted(matrix[i])

    # Sort each column
    for j in range(col_count):
        column = [matrix[i][j] for i in range(row_count)]
        column = sorted(column)
        for i in range(row_count):
            matrix[i][j] = column[i]

    return matrix

def count_unique_paths_obstacles(obstacleGrid):
    m, n = len(obstacleGrid), len(obstacleGrid[0])
    dp = [[0] * n for _ in range(m)]
    if obstacleGrid[0][0] == 0:
        dp[0][0] = 1
    for i in range(m):
        for j in range(n):
            if obstacleGrid[i][j] == 0 and (i > 0 or j > 0):
                dp[i][j] = dp[i-1][j] + dp[i][j-1] if i > 0 and j > 0 else (dp[i-1][j] if i > 0 else dp[i][j-1])
    return dp[m-1][n-1]

