def fib_number(n):
    if n <= 1:
        return n
    fib = [0] * (n + 1)
    fib[0] = 0
    fib[1] = 1
    for i in range(2, n + 1):
        fib[i] = fib[i - 1] + fib[i - 2]
    return fib[n]

def catalan_number(n):
    result = 1
    for i in range(2, n + 1):
        result = result * (n + i) / i
    return int(result)

def highest_power_of_two(n):
    power = 0
    while (1 << power) <= n:
        power += 1
    return power - 1

