def nthTribonacci(n):
    if n == 1 or n == 2:
        return 1
    if n == 3:
        return 2
    trib = [0] * (n+1)
    trib[1] = 1
    trib[2] = 1
    trib[3] = 2
    mod = 1000000007
    for i in range(4,n+1):
        trib[i] = (trib[i-1] % mod + trib[i-2] % mod + trib[i-3] % mod) % mod
    return trib[n]

