def alternate_merge(str1: str, str2: str) -> str:
    merged_str = ''
    i, j = 0, 0
    while i < len(str1) and j < len(str2):
        merged_str += str1[i] + str2[j]
        i += 1
        j += 1
    if i < len(str1):
