def matrix_reshape(mat, r, c):
    m = len(mat)
    n = len(mat[0])

    if m*n != r*c: 
        return mat

    output = [[0 for x in range(c)]for x in range(r)]

    x =0
    for i in range(m):
        for j in range(n):
            output[x//c][x%c] = mat[i][j]
            x +=1      

    return output

def n_choose_k(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k) 
    numerator = 1
    for i in range(n, n - k, -1):
        numerator *= i
    denominator = 1
    for i in range(1, k + 1):
        denominator *= i
    return int(numerator / denominator)

from collections import deque

def find_longest_common_subarray(nums1, nums2):
    answer = 0

    if len(nums1) < len(nums2):
        nums1, nums2 = nums2, nums1

    nums1, nums2 = deque(nums1), deque(nums2)
    for _ in range(len(nums2) - 1):
        nums1.appendleft(-1)
        nums1.append(-1)
    nums1.appendleft(-1)

    for i in range(len(nums1) - len(nums2)):
        nums1.popleft()
        count, flag = 0, False
        for j in range(len(nums2)):
            if nums1[j] == nums2[j]:
                if not flag:
                    flag = True
                count += 1
            else:
                count, flag = 0, False
            answer = max(answer, count)

    return answer

def closest_three_sum(nums, target):
    nums.sort()
    closest = 10**6
    for idx in range(len(nums)-2):
        if idx==0 or nums[idx]!=nums[idx-1]:
            left = idx+1
            right = len(nums)-1
            while left < right:
                total = nums[idx]+nums[left]+nums[right]
                if abs(closest-target) > abs(total-target):
                    closest = total
                if total > target:
                    right-=1
                elif total < target:
                    left+=1
                else:
                    return target
    return closest

def min_del_to_make_anagrams(s1, s2):
    count1 = [0]*26
    count2 = [0]*26
    res = 0

    for i in range(len(s1)):
        count1[ord(s1[i])-ord('a')] += 1
    for i in range(len(s2)):
        count2[ord(s2[i])-ord('a')] += 1

    for i in range(26):
        res += abs(count1[i] - count2[i])

