def three_sum_count(nums):
    nums.sort()
    count = 0
    for i in range(len(nums) - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        left, right = i + 1, len(nums) - 1
        while left < right:
            s = nums[i] + nums[left] + nums[right]
            if s < 0:
                left += 1
            elif s > 0:
                right -= 1
            else:
                count += 1
                while left < right and nums[left] == nums[left + 1]:
                    left += 1
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1
                left += 1
                right -= 1
    return count

def leastBricks(wall):
    num_rows = len(wall)
    min_bricks = num_rows
    edges_at = {}
    wall_width = 0

    if len(wall[0]) == 1 and wall[0][0] == 1:
        return num_rows

    for row in wall:
        position = 0
        for brick in row:
            position += brick
            if position not in edges_at:
                edges_at[position] = 0
            edges_at[position] += 1
        if wall_width == 0:
            wall_width = position

    for position in edges_at:
        if 0 < position < wall_width:
            bricks_crossed = num_rows - edges_at[position]
            min_bricks = min(min_bricks, bricks_crossed)

    return min_bricks

def min_del_to_make_equal(str1, str2):
    m, n = len(str1), len(str2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m):
        for j in range(n):
            if str1[i] == str2[j]:
                dp[i + 1][j + 1] = dp[i][j] + 1
            else:
                dp[i + 1][j + 1] = max(dp[i + 1][j], dp[i][j + 1])

    return m - dp[m][n] + n - dp[m][n]

from collections import Counter

def rearrange_characters(s: str, target: str) -> int:
    ans = float('inf')
    cnt = Counter(s)
    for c, num in Counter(target).items():
        ans = min(ans, cnt[c] // num)
        if ans == 0:
            return 0
    return ans

