def valid_parentheses_sequences(n):
    catalan = [0 for _ in range(n + 1)]
    catalan[0] = 1
    catalan[1] = 1

    for i in range(2, n + 1):
        for j in range(i):
            catalan[i] += (catalan[j] * catalan[i - j - 1])

    return catalan[n]

def smallest_missing_coin(coins):
