def valid_parenthesis(parenthesis_list):
    stack = []
    for p in parenthesis_list:
        if p == "(":
            stack.append(p)
        elif p == ")":
            if stack:
                stack.pop()
            else:
                return False
    return len(stack) == 0

memo = {}

def factorial_memo(n):
    if n == 0:
        return 1
    if n in memo:
        return memo[n]
    else:
        num = n * factorial_memo(n-1)
        memo[n] = num
        return num

def longestSubarray(nums):
    left = 0
    zero_count = 0
    max_len = 0
    for right in range(len(nums)):
        if nums[right] == 0:
            zero_count += 1
        while zero_count > 1:
            if nums[left] == 0:
                zero_count -= 1
            left += 1
        max_len = max(max_len, right - left)
    return max_len

def find_max_subarray_length(A, B):
    if not A or not B: return 0

    RADIX = 10
    MOD = 10 ** 9 + 7
    Pinv = pow(RADIX, MOD - 2, MOD)  # Fermat's Little Theorem
    def rolling_hash_iter(arr, k):
        if k > len(arr): return
        h = 0; power = 1
        for i, val in enumerate(arr):
            h = (h + val * power) % MOD
            if i + 1 < k:
                power = (power * RADIX) % MOD
            else:
                yield h, i-k+1
                h = (h - arr[i-k+1]) * Pinv % MOD

    def has_substr_match(k):
        if 0 == k: return True
        from collections import defaultdict
        hash2inds = defaultdict(list)
        for h, i in rolling_hash_iter(A, k):
            hash2inds[h].append(i)
        for h, j in rolling_hash_iter(B, k):
            ref = None
            for i in hash2inds[h]:
                ref = ref or B[j:(j+k)]
                if A[i:(i+k)] == ref:
                    return True
        return False

    lo = 0
    hi = min(len(A), len(B)) + 1
    while lo < hi:
        k = (lo + hi) // 2
        if has_substr_match(k):
            lo = k + 1
        else:
            hi = k
    return lo - 1

def longestZigzag(nums):
    if len(nums) < 2:
        return len(nums)

    up = [1] * len(nums)
    down = [1] * len(nums)

    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            up[i] = down[i - 1] + 1
        elif nums[i] < nums[i - 1]:
            down[i] = up[i - 1] + 1

    return max(max(up), max(down))

