def is_palindrome_anagram(s: str) -> bool:
    """
    Determines if the given string can form a palindrome anagram.

    :param s: Input string to check.
    :return: True if s can form a palindrome anagram, False otherwise.
    """
    char_counts = {}
    for char in s:
        char_counts[char] = char_counts.get(char, 0) + 1

    odd_count = 0
    for count in char_counts.values():
        if count % 2 != 0:
            odd_count += 1
        if odd_count > 1:
            return False

    return True

def longest_Substring_Without_Repeat(s):
    char_map = {}
    left = 0
    result = 0
    for right in range(len(s)):
        if s[right] in char_map:
            left = max(left, char_map[s[right]] + 1)
        char_map[s[right]] = right
        result = max(result, right - left + 1)
    return result

