def getMaxRepetitions(s1: str, n1: int, s2: str, n2: int) -> int:
    # Check if s2 can be formed with characters from s1
    count_s1 = Counter(s1)
    count_s2 = Counter(s2)

    for ch in count_s2:
        if ch not in count_s1:
            return 0

    l1, l2 = len(s1), len(s2)
    i1, i2 = 0, 0
    dic = {}
    total = l1 * n1

    while i1 < total:
        if s1[i1 % l1] == s2[i2 % l2]:
            if (i1 % l1, i2 % l2) in dic:
                prev1, prev2 = dic[(i1 % l1, i2 % l2)]
                cir1, cir2 = i1 - prev1, i2 - prev2
                count_cir1 = (total - i1) // cir1
                i1 += count_cir1 * cir1
                i2 += count_cir1 * cir2
                if i1 >= total: break
            else:
                dic[(i1 % l1, i2 % l2)] = (i1, i2)
            i2 += 1
        i1 += 1
    return i2 // (l2 * n2)

