        self.next = None

def create_linked_list(lst):
    if len(lst) == 0:
        return None
    head = ListNode(lst[0])
    current = head
    for i in range(1, len(lst)):
        current.next = ListNode(lst[i])
        current = current.next
    return head

def partition_list(head, x):
    left_head = left = ListNode(0)
    right_head = right = ListNode(0)
    current = head
    while current:
        if current.val < x:
            left.next = current
            left = left.next
        else:
            right.next = current
            right = right.next
        current = current.next
    left.next = right_head.next
    right.next = None
    return left_head.next

def linked_list_to_list(head):
    lst = []
    current = head
    while current:
        lst.append(current.val)
        current = current.next
    return lst

def partition_linked_list(lst, x):
    head = create_linked_list(lst)
    partitioned_head = partition_list(head, x)
    return linked_list_to_list(partitioned_head)

