def find_min_unique_ints(arr: List[int], k: int) -> int:
    counts = {}
    for num in arr:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1
    freqs = sorted([(count, num) for num, count in counts.items()])
    unique_ints = len(freqs)
    for count, _ in freqs:
        if count <= k:
            k -= count
            unique_ints -= 1
        else:
            break
    return unique_ints

