def min_operations_to_permutation(target: List[int], arr: List[int]) -> int:
    # Map each target element to its index
    target_index = {t: i for i, t in enumerate(target)}

    # Store the sequence in arr that appears in target, with their target indices
    sequence = [target_index[num] for num in arr if num in target_index]

    # Apply patience sorting algorithm to find the longest increasing subsequence
    lis = []
    for num in sequence:
        if not lis or num > lis[-1]:
            lis.append(num)
        else:
            # Find the position to replace in the LIS
            idx = bisect.bisect_left(lis, num)
            lis[idx] = num
    # The difference between len(target) and the length of LIS gives us the number of insertions needed
    return len(target) - len(lis)

