def super_egg_drop(K: int, N: int):
    def solve(k, moves):
        dp = [None] * (k + 1)
        for i in range(k + 1):
            dp[i] = [0] * (moves + 1)

        for i in range(1, k + 1):
            for j in range(1, moves + 1):
                dp[i][j] = 1 + dp[i - 1][j - 1] + dp[i][j - 1]
        return dp[k][moves]

    left, right = 1, N + 1
    while left < right:
        mid = (left + right) // 2
