def validate_IPv4(ip):
    # IP address is composed of 4 parts separated by period
    parts = ip.split('.')

    # There must be exactly 4 parts
    if len(parts) != 4:
        return False

    for part in parts:
        # Each part must be a number
        if not part.isdigit():
            return False

        # Leading zeros are not allowed
        if part[0] == '0' and len(part) > 1:
            return False

        # Each part must be between 0 and 255
        if not 0 <= int(part) <= 255:
            return False

    return True

