def longest_dup_substring(S):
    res, l, r, a_num, mod = '', 0, len(S)-1, ord('a'), 2**63-1
    while l <= r:
        tmp, id, existence, size = None, 0, set(), l+(r-l)//2
        tem = 26**(size-1) % mod
        for i in range(0, size):
            id = id*26+ord(S[i])-a_num
        id %= mod
        existence.add(id)
        for i in range(size, len(S)):
            tail, prev_head = S[i], S[i-size]
            id = (id - (ord(prev_head)-a_num)*tem)*26+ord(tail)-a_num
            id %= mod
            if id in existence:
                tmp = S[i-size+1:i+1]
                break
            existence.add(id)
        if tmp:
            l = size+1
            res = tmp
        else:
            r = size-1
    return res

