def get_good_suffix_shift(pattern):
    good_suffix_shift = [len(pattern)] * (len(pattern) + 1)
    border_position = [0] * (len(pattern) + 1)
    i = len(pattern)
    j = len(pattern) + 1
    border_position[i] = j

    while i > 0:
        while j <= len(pattern) and pattern[i - 1] != pattern[j - 1]:
            if good_suffix_shift[j] == len(pattern):
                good_suffix_shift[j] = j - i
            j = border_position[j]
        i -= 1
        j -= 1
        border_position[i] = j

    j = border_position[0]
    for i in range(len(pattern) + 1):
        if good_suffix_shift[i] == len(pattern):
            good_suffix_shift[i] = j
        if i == j:
            j = border_position[j]

    return good_suffix_shift

def boyer_moore_search(text, pattern):
    bad_char_shift = get_bad_character_shift(pattern)
    good_suffix_shift = get_good_suffix_shift(pattern)

    i = len(pattern) - 1
    while i < len(text):
        j = len(pattern) - 1
        while text[i] == pattern[j]:
            if j == 0:
                return i
            i -= 1
            j -= 1

        bad_char_shift_value = bad_char_shift.get(text[i], len(pattern))
        good_suffix_shift_value = good_suffix_shift[j + 1]
        i += max(bad_char_shift_value, good_suffix_shift_value)

    return -1

