        while q:
            cur = q.popleft()
            if not visited[cur]:
                visited[cur] = True
                for neighbor in range(len(isConnected)):
                    if isConnected[cur][neighbor] == 1 and not visited[neighbor]:
                        q.append(neighbor)

    n = len(isConnected)
    visited = [False] * n
    circles = 0

    for i in range(n):
        if not visited[i]:
            bfs(i)
            circles += 1

    return circles

