from functools import lru_cache

def pattern_matching(s: str, pattern: str) -> bool:
    @lru_cache(maxsize=None)
    def match(i: int, j: int) -> bool:
        if j == len(pattern):
            return i == len(s)
        if i < len(s) and (pattern[j] == '?' or pattern[j] == s[i]):
            return match(i + 1, j + 1)
        if j + 1 < len(pattern) and pattern[j + 1] == '*':
            return match(i, j + 2) or (i < len(s) and match(i + 1, j))
        return False
    return match(0, 0)

