def quicksort_random_pivot(numbers):
    if len(numbers) <= 1:
        return numbers
    else:
        pivot = random.choice(numbers)
        less = [i for i in numbers if i < pivot]
        equal = [i for i in numbers if i == pivot]
        greater = [i for i in numbers if i > pivot]
        return quicksort_random_pivot(less) + equal + quicksort_random_pivot(greater)

