def count_negative_numbers(grid: list[list[int]]) -> int:
    def search(row: list[int], edge: int) -> int:
        n = len(row)
        if edge == n:
            return edge
        l = edge
        r = n - 1
        while l <= r:
            m = l + (r - l) // 2
            if row[m] >= 0:
                l = m + 1
            else:
                r = m - 1
        return l

    m = len(grid)
    n = len(grid[0])
    edge = 0
    count = 0
    for i in range(m - 1, -1, -1):
        edge = search(grid[i], edge)
        count += n - edge
    return count

