def translate_number(num):
    num_str = str(num)
    dp = [0] * (len(num_str) + 1)
    dp[0], dp[1] = 1, 1
    for i in range(2, len(num_str) + 1):
        if 0 < int(num_str[i - 1:i]):
            dp[i] = dp[i - 1]
        if 10 <= int(num_str[i - 2:i]) <= 25:
            dp[i] += dp[i - 2]
