from collections import defaultdict

def check_valid_tree(n, edges):
    if n <= 0 or len(edges) != n - 1:
        return False

    graph = defaultdict(list)
    for edge in edges:
        u, v = edge
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n

    def dfs(node, parent):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                if not dfs(neighbor, node):
                    return False
            elif neighbor != parent:
                return False
        return True

    if not dfs(0, -1):
        return False

    return all(visited)

