def numberToWords(num):
    to19 = 'Zero One Two Three Four Five Six Seven Eight Nine Ten Eleven Twelve ' \
           'Thirteen Fourteen Fifteen Sixteen Seventeen Eighteen Nineteen'.split()
    tens = 'Twenty Thirty Forty Fifty Sixty Seventy Eighty Ninety'.split()

    def words(n):
        if n < 20:
            return to19[n]
        if n < 100:
            return tens[n//10-2] + ('' if n % 10 == 0 else ' ' + to19[n % 10])
        if n < 1000:
            return to19[n//100] + ' Hundred' + ('' if n % 100 == 0 else ' ' + words(n % 100))
        for p, w in enumerate(('Thousand', 'Million', 'Billion'), 1):
            if n < 1000**(p+1):
                return words(n//1000**p) + ' ' + w + ('' if n % 1000**p == 0 else ' ' + words(n % 1000**p))

    return words(num)

