def anagram_pairs(words):
    """
    Counts the number of unique anagram pairs in a given list of words.
    """
    anagram_groups = {}
    for word in words:
        # Create a sorted tuple of characters to uniquely identify anagrams
        sorted_word = tuple(sorted(word))
        if sorted_word in anagram_groups:
            anagram_groups[sorted_word].append(word)
        else:
            anagram_groups[sorted_word] = [word]

    # Count the number of anagram groups with more than one word
    return sum(1 for group in anagram_groups.values() if len(group) > 1)

