def minimumLengthEncoding(words: List[str]) -> int:
    """
    Build a trie from the reversed strings
    and count the number of leaves

    We reverse the words:
        [ time, me, bell ] -> [ emit, em, lleb ]
    To build the trie

    Time: O(n * m)
    Space: O(n * m)
        n - number of words
        m - max length of the words
    """
    trie = {}

    # create trie
    for word in words:
        node = trie
        for i in range(len(word) - 1, -1, -1):
            node = node.setdefault(word[i], {})

    # get count
    def traverse(node, depth):
        if not node:
            return depth + 1  # extra char for ending
        return sum([traverse(child, depth + 1) for child in node.values()])

    return traverse(trie, 0)

def partition(nums, low, high):
    pivot = nums[high]
    i = low - 1
    for j in range(low, high):
        if nums[j] <= pivot:
            i += 1
            nums[i], nums[j] = nums[j], nums[i]
    nums[i + 1], nums[high] = nums[high], nums[i + 1]
    return i + 1

def quickSelect(nums, k, low, high):
    if low == high:
        return nums[low]
    pivot_index = partition(nums, low, high)
    if k == pivot_index:
        return nums[k]
    elif k < pivot_index:
        return quickSelect(nums, k, low, pivot_index - 1)
    else:
        return quickSelect(nums, k, pivot_index + 1, high)

