    queue = [(x1, y1, 0)]
    visited = set([(x1, y1)])
    while queue:
        x, y, c = queue.pop(0)
        if x == x2 and y == y2:
            return c
        for dx, dy in moves:
            nx, ny = x + dx, y + dy
            if 0 <= nx < 8 and 0 <= ny < 8 and (nx, ny) not in visited:
