def relative_sort(arr1: List[int], arr2: List[int]) -> List[int]:
    count_map = Counter(arr1)
    sorted_arr = []
    remaining = []

    for num in arr2:
        while count_map.get(num, 0) > 0:
            sorted_arr.append(num)
            count_map[num] -= 1

    for num in arr1:
        if num not in arr2 and count_map[num] > 0:
            remaining.append(num)
            count_map[num] -= 1

    remaining.sort()
    return sorted_arr + remaining

