        dx3, dy3 = p3[0] - p2[0], p3[1] - p2[1]

        if dx1 * dx2 + dy1 * dy2 == 0 or dx1 * dx3 + dy1 * dy3 == 0 or dx2 * dx3 + dy2 * dy3 == 0:
            return True
        return False

    for i in range(len(points)):
        for j in range(i + 1, len(points)):
