    res = 0
    fac = [factorial(i) for i in range(7)]

    def f(i, n1, n2, c1, c2, j=1):
        nonlocal res
        if n1 > n // 2 or (i - n1) > n // 2: return
        if i == m:
            if n1 == n2 and c1 == c2:
                res += j
            return
        x = balls[i]
        for k in range(x+1):
            f(i+1, n1+k, n2+(x-k), c1+(k!=0), c2+(k!=x), j*comb(x, k))
    f(0,0,0,0,0)
    return res / total

