    for i in range(n-1, -1, -1):
        dp[i][i] = 1
        for j in range(i+1, n):
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])
    last_element = s[0]
    for i in range(n):
        for j in range(n):
            if dp[i][j] > dp[0][0] - 1:
                last_element = s[j]
    return last_element

