from math import sqrt

def max_points_covered(points, r):
    N = len(points)
    max_res = 1
    map_t = set()
    r2 = r ** 2

    def get_mid(a, b):
        ax, ay = a
        bx, by = b
        lx = bx - ax
        ly = by - ay
        lxy = sqrt(lx ** 2 + ly ** 2)
        if (lxy / 2) ** 2 > r2:
            return (None, None), (None, None)
        l = sqrt(r2 - (lxy / 2) ** 2)
        yy = l * lx / lxy
        xx = l * ly / lxy
        mx = (ax + bx) / 2
        my = (ay + by) / 2
        return (mx + xx, my - yy), (mx - xx, my + yy)

    def is_in(rx, ry, x, y):
        return (rx - x) ** 2 + (ry - y) ** 2 <= r2 + 0.01

    def count_in(rx, ry):
        return sum(is_in(rx, ry, x, y) for x, y in points)

    for ii in range(N):
        for jj in range(ii + 1, N):
            (rx1, ry1), (rx2, ry2) = get_mid(points[ii], points[jj])
            if rx1 is None:
                continue
            if (rx1, ry1) not in map_t:
                c1 = count_in(rx1, ry1)
            else:
                c1 = 0
            if (rx2, ry2) not in map_t:
                c2 = count_in(rx2, ry2)
            else:
                c2 = 0
            map_t.add((rx1, ry1))
            map_t.add((rx2, ry2))
            max_res = max(c1, c2, max_res)
    return max_res

