    if not root:
        return 0

    queue = deque([root])
    leaf_count = 0

    while queue:
        node = queue.popleft()
        if not node.left and not node.right:
            leaf_count += 1
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)

    return leaf_count

