def smallest_diff(arr):
    arr.sort()
    min_diff = float('inf')
    for i in range(1, len(arr)):
        if arr[i] - arr[i-1] < min_diff:
            min_diff = arr[i] - arr[i-1]
    return min_diff

def sum_even_product_odd(nums):
    sum_even = 0
    product_odd = 1
    for num in nums:
        if num % 2 == 0:
            sum_even += num
        else:
            product_odd *= num
    if sum_even == 0 and 0 in nums:
        sum_even = 0
    return (sum_even, product_odd)

