def intervals_intersection(list1, list2):
    result = []
    i = 0
    j = 0
    while i < len(list1) and j < len(list2):
        start = max(list1[i][0], list2[j][0])
        end = min(list1[i][1], list2[j][1])
        if start <= end:
            result.append([start, end])
        if list1[i][1] < list2[j][1]:
            i += 1
        else:
            j += 1
    return result

def is_Perfect_Power(n):
    if n < 2:
        return False
    for base in range(2, int(n**0.5) + 1):
        exponent = 2
        while base**exponent <= n:
            if base**exponent == n:
                return True
            exponent += 1
    return False

def longestLCIS(nums):
