def matrix_addition(A, B):
    n1 = len(A)
    n2 = len(A[0])
    newA = [[0] * n2 for _ in range(n1)]
    for i in range(n1):
        for j in range(n2):
            newA[i][j] = A[i][j] + B[i][j]
    return newA

