from collections import defaultdict

def find_circle_num(isConnected):
    visit = set()
    province, n = 0, len(isConnected)

    def dfs(city, visit):
        visit.add(city)

        for another, isConnect in enumerate(isConnected[city]):
            if another != city and isConnect == 1 and another not in visit:
                dfs(another, visit)

    for city in range(n):
        if city not in visit:
            province += 1
            dfs(city, visit)

    return province

def multiply(mat1, mat2):
    m = len(mat1)
    n = len(mat2[0])
    answer = []
    for i in range(m):
        t = []
        for r in range(n):
            tmp = 0
            for j in range(len(mat1[0])):
                tmp += mat1[i][j] * mat2[j][r]
            t.append(tmp)
        answer.append(t)
    return answer

def union_array(nums1, nums2):
    for i in range(len(nums1)-1, -1, -1):
        if nums1[i] == 0:
            nums1.pop(i)
        else:
            break
    for i in range(len(nums2)-1, -1, -1):
        if nums2[i] == 0:
            nums2.pop(i)
        else:
            break
    n1 = len(nums1)
    n2 = len(nums2)
    i = 0
    j = 0
    while i < n1 and j < n2:
        if i < n1 and nums1[i] <= nums2[j]:
            i += 1
        if j < n2 and nums1[i] > nums2[j]:
            nums1.insert(i, nums2[j])
            i += 1
            j += 1
    if j < n2:
        nums1.extend(nums2[j:])
    return nums1

