def find_longest_zeros(number):
    binary_str = bin(number)[2:] 
    max_gap = 0
    current_gap = 0

    for bit in binary_str:
        if bit == '0':
            current_gap += 1
        elif bit == '1':
            if current_gap > max_gap:
                max_gap = current_gap
            current_gap = 0

    return max_gap

