def find_perfect_numbers(start, end):
    def is_perfect(n):
        sum = 1
        i = 2
        while i <= n/i:
            if n % i == 0:
                sum += i+int(n/i)
            i+=2
        if i*i == n:
            sum -= i
        return sum == n and n!=1

    perfect_numbers = []
    for num in range(start, end+1):
        if is_perfect(num):
            perfect_numbers.append(num)
    return perfect_numbers

def count_set_bits(n):
