def findCombinations(nums, k):
    if len(nums) < k:
        return []
    if len(nums) == k:
        return [nums]
    if k == 1:
        return [[x] for x in nums]
    res = []
    for i in range(len(nums)):
        for subset in findCombinations(nums[i+1:], k-1):
            res.append([nums[i]] + subset)
    return res

from functools import lru_cache

def count_pattern_as_subsequence(text: str, pattern: str) -> int:
    len_text = len(text)
    len_pattern = len(pattern)

    @lru_cache(maxsize=None)
    def dp(i, j):
        if j == len_pattern:
            return 1
        if i == len_text:
            return 0
        if text[i] == pattern[j]:
            return dp(i + 1, j + 1) + dp(i + 1, j)
        else:
            return dp(i + 1, j)

    return dp(0, 0)

